// A small, enclosed café built from LimeZu's free Modern Interiors pack.
// The tileset is generated by scripts/build-limezu-tileset.py (see there for
// how to get the pack); it stacks the Room Builder sheet, the Interiors sheet
// and our own coffee bar, 17 tiles wide.
//
// Layers are indexed layer[x][y]; -1 means empty. Any non-empty tile in an
// objmap layer blocks movement, so walls and furniture go there; the rug and
// chairs go in bg layers so travelers can walk onto a chair's seat and sit.

export const tilesetpath = '/ai-town/assets/limezu/cafe-tileset.png';
export const tiledim = 32;
export const tilesetpxw = 544;
export const tilesetpxh = 3680;

const COLS = 17;
const ROOM_ROWS = 23;
const INTERIOR_ROWS = 89;
// Tile index in the Room Builder sheet (17 wide), the Interiors sheet (16
// wide) or the coffee bar (counted as 16 wide too).
const R = (n) => n;
const I = (n) => (ROOM_ROWS + Math.floor(n / 16)) * COLS + (n % 16);
const C = (n) => (ROOM_ROWS + INTERIOR_ROWS + Math.floor(n / 16)) * COLS + (n % 16);

const W = 24;
const H = 16;
export const mapwidth = W;
export const mapheight = H;
export const screenxtiles = W;
export const screenytiles = H;

const layer = () => Array.from({ length: W }, () => Array(H).fill(-1));
const floor = layer();
const rug = layer();
const chairs = layer();
const walls = layer();
const chairBacks = layer();
const furniture = layer();
const tabletop = layer();

// Copy a w x h block of tiles starting at sheet index `start` to (x, y).
const block = (grid, x, y, sheet, start, w, h) => {
  const width = sheet === R ? 17 : 16;
  for (let dx = 0; dx < w; dx++) {
    for (let dy = 0; dy < h; dy++) grid[x + dx][y + dy] = sheet(start + dy * width + dx);
  }
};

const CEILING = R(12);
const DOOR = [11, 12];
// Guests arrive and leave through these tiles in the bottom wall.
export const door = DOOR.map((x) => ({ x, y: H - 1 }));

// Cream tile floor (3x2 repeating block), dark "ceiling" around the room.
for (let x = 0; x < W; x++) {
  for (let y = 0; y < H; y++) {
    floor[x][y] = R(130 + (y % 2) * 17 + (x % 3));
  }
}
for (let x = 0; x < W; x++) {
  if (!DOOR.includes(x)) walls[x][H - 1] = CEILING;
}
for (let y = 0; y < H - 1; y++) {
  walls[0][y] = CEILING;
  walls[W - 1][y] = CEILING;
}

// Two-tile-tall back wall.
for (let x = 1; x < W - 1; x++) {
  walls[x][0] = R(86);
  walls[x][1] = R(103);
}

// Back wall: fireplace, windows, paintings, and the bar's bottle shelves.
block(furniture, 2, 0, I, 1092, 2, 3);
block(furniture, 6, 0, I, 391, 2, 2);
block(furniture, 10, 0, I, 391, 2, 2);
block(furniture, 8, 1, I, 1136, 1, 1);
block(furniture, 13, 1, I, 1138, 1, 1);
block(furniture, 16, 0, I, 1098, 6, 3);

// Coffee counter in front of the shelves, with cakes on display. Guests
// order standing at one of the spots in front of it.
block(furniture, 16, 3, C, 0, 6, 3);
block(tabletop, 20, 4, I, 220, 1, 1);
block(tabletop, 21, 4, I, 219, 1, 1);
export const counter = [17, 19, 21].map((x) => ({ x, y: 6 }));

// Where travelers can sit: the lower (seat) tile of each chair, which way they
// face, and which table it belongs to. The chair's upper tile is blocked with
// an invisible tile.
export const seats = [];
const chair = (x, y, start, facing, table) => {
  block(chairs, x, y, I, start, 1, 2);
  chairBacks[x][y] = R(0);
  seats.push({ x, y: y + 1, facing, table });
};

// Four tables with a chair on each side and something to eat on top.
const tables = [
  [3, 6],
  [8, 6],
  [3, 10],
  [8, 10],
];
const food = [203, 219, 220, 235];
tables.forEach(([x, y], i) => {
  block(furniture, x, y, I, 161, 2, 2);
  chair(x - 1, y, 342, 'right', i);
  chair(x + 2, y, 343, 'left', i);
  block(tabletop, x, y, I, food[i], 1, 1);
});

// Lounge corner: rug, sofa, bookshelf.
block(rug, 14, 9, I, 247, 4, 3);
block(furniture, 14, 12, I, 296, 3, 2);
block(furniture, 20, 8, I, 229, 2, 4);

// Plants.
block(furniture, 1, 13, I, 732, 1, 2);
block(furniture, W - 2, 13, I, 732, 1, 2);
block(furniture, 22, 3, I, 732, 1, 2);

export const bgtiles = [floor, rug, chairs];
export const objmap = [walls, chairBacks, furniture, tabletop];

export const animatedsprites = [];
